import sympy

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def has_roots_mod_p(f, p):
    # Compute the Legendre symbol (p|f(x))
    # using the quadratic reciprocity law
    if p % 4 == 1:
        return sympy.little_a(f, p)
    else:
        return -sympy.little_a(f, p)

def little_a(f, p):
    # Compute the Legendre symbol (p|f(x))
    # using the quadratic reciprocity law
    if p % 4 == 1:
        return 1
    elif p % 4 == 3:
        return -1
    else:
        return 1

